/* Estilos Página de Vídeos - Stitch Edition 2026 */
.videos-header-box {
    margin-bottom: 2.5rem;
    padding-bottom: 2rem;
    border-bottom: 1px solid rgba(22, 28, 34, 0.08);
}
.videos-top-meta {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.2rem;
}
.videos-badge-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(164, 60, 27, 0.08);
    border: 1px solid rgba(164, 60, 27, 0.2);
    border-radius: 9999px;
    padding: 4px 14px;
}
.videos-badge-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background-color: #A43C1B;
    box-shadow: 0 0 8px #A43C1B;
}
.videos-badge-text {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.74rem;
    font-weight: 800;
    color: #A43C1B;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}


.videos-title {
    font-family: 'Playfair Display', serif;
    font-size: 2.7rem;
    font-weight: 700;
    color: #151C22;
    margin: 0 0 0.6rem 0;
    line-height: 1.2;
    letter-spacing: -0.01em;
}
.videos-subtitle {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 1.08rem;
    color: #555555;
    line-height: 1.55;
    margin: 0;
    max-width: 820px;
}

/* Featured Video Hero Box */
.videos-featured-wrapper {
    box-shadow: 0 16px 40px rgba(28, 25, 23, 0.15) !important;
}
.featured-badge-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 0.8rem;
}
.featured-pill-badge {
    display: inline-block;
    background: #A43C1B;
    color: #FFFFFF;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.1em;
    padding: 3px 12px;
    border-radius: 9999px;
}
.featured-duration-badge {
    color: #A8A29E;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.75rem;
    font-weight: 600;
}
.featured-video-title {
    font-family: 'Playfair Display', serif;
    font-size: 1.85rem;
    font-weight: 700;
    color: #FFFFFF;
    margin: 0 0 0.5rem 0;
    line-height: 1.25;
}
.featured-video-subtitle {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.95rem;
    color: #D6D3D1;
    margin: 0 0 1.5rem 0;
    line-height: 1.5;
    max-width: 780px;
}

/* Section Divider Headers */
.section-divider-header {
    margin: 3.5rem 0 1.8rem 0;
    padding-bottom: 0.8rem;
    border-bottom: 1px solid rgba(22, 28, 34, 0.08);
}
.section-kicker {
    display: block;
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.72rem;
    font-weight: 800;
    color: #A43C1B;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 0.35rem;
}
.section-main-heading {
    font-family: 'Playfair Display', serif;
    font-size: 2rem;
    font-weight: 700;
    color: #151C22;
    margin: 0 0 0.4rem 0;
}
.section-sub-heading {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.98rem;
    color: #666666;
    margin: 0;
    max-width: 750px;
    line-height: 1.5;
}

/* YouTube Video Grid Cards */
.video-grid-card {
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.35s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s ease !important;
    overflow: hidden !important;
