    border-color: rgba(164, 60, 27, 0.3) !important;
}
.video-grid-card .elementor-widget-video {
    margin-bottom: 0 !important;
}
.video-card-meta-box {
    padding: 1.25rem 1.35rem 1.4rem 1.35rem;
