    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: rgba(164, 60, 27, 0.08);
    padding: 2px 9px;
    border-radius: 9999px;
    margin-bottom: 0.6rem;
}
.video-card-title {
    font-family: 'Playfair Display', serif;
    font-size: 1.18rem;
    font-weight: 700;
    color: #151C22;
    line-height: 1.35;
    margin: 0 0 0.5rem 0;
}
.video-card-desc {
    font-family: 'Plus Jakarta Sans', sans-serif;
    font-size: 0.85rem;
    color: #666666;
    line-height: 1.5;
    margin: 0;
}

